"Annual leave is taken in one or two parts (at the Employee's request and in more parts if the work process allows); the first part lasts at least {0} working days without interruption during the year, and the remainder no later than {1} of the following year ({2}). The Employer adopts a leave plan by {3} after consulting the Employee and delivers the leave decision no later than {4} days before the leave begins ({5} and {6}). During annual leave the Employee is entitled to salary compensation in the amount of the salary he or she would have earned had he or she worked ({7}).",
"Annual leave is taken in one or two parts, and at the employee's request in several parts if the work process allows. The first part lasts at least {0} working days uninterrupted during the calendar year, and the remainder is used no later than {1} of the following year ({2}). An employee who has not used leave or interrupted it because of temporary incapacity for work or child care uses it on return, no later than {3} months after the end of the year in which the right was acquired; because of maternity, paternity or parental leave — within {4} months of returning to work.",
"Annual leave is determined in working days according to a {0}-day working week ({1}); non-working holidays, paid absence and temporary incapacity for work are not counted in leave days. The base is {2} working days ({3}); an employee under 18 is entitled to at least {4} working days ({5}), a person with a disability to at least {6} ({7}), and an employee working reduced hours to {8} working days.",
