"Default",
"Off by default: goods on an issue form have not been sold (VAT Act Art. 4 para. 1 — a supply is a transfer of the right to dispose), they remain the trader's property and are discharged only by an invoice; a return has no entry (Rulebook 34/12 Art. 7 col. 5). On: the recipient disposes of the goods, the delivery has been made (VAT no later than 8 days after handover, VAT Act Art. 18 para. 3) — discharge on the date of the issue form at retail price (MPC), a return as a negative discharge, and an invoice from the issue form does not discharge again. The regulation does not mention issue forms; the choice should be confirmed with the accountant.",
