"Procedure — {0} · {1}",
"The procedure was initiated by a written warning of {0}, delivered to the employee with a {1}-day period for a written statement and the right to an oral statement. {2} {3}it was established that the employee committed the breach described in the operative part, which at the time of commission was defined by the employment contract and the Rulebook (Art. 144 para. 4 ZOR).",
"The proceedings were not found.",
"Procedure under the law (",
"The procedure is initiated by the executive director upon learning of the breach or on the initiative of any employee, by a written warning to the employee within {0} days of learning of it. The warning contains the employee's personal data and position, a description and timeframe of the breach, evidence and a notice of the right to an oral statement. The employee gives a written statement within {1} days of delivery (silence is deemed consent with the allegations), and within {2} days may request an oral statement; the hearing is held within 15 days of delivery of the warning, with the employee's right to the presence of a trade union representative and a defender, and minutes are kept ({3}). The decision — to discontinue the procedure, release from liability or a measure — is made by the executive director within {4} days of the expiry of the deadline for a statement or of the hearing (30 days with an inspection or expert examination); the decision contains an introduction, operative part, reasoning and instructions on legal remedy, is final and is delivered within {5} days. The employee may challenge it within {6} days before the Agency for Peaceful Resolution of Labour Disputes, and in the case of termination and conditional termination also before a court ({7}).",
"The procedure may be initiated within {0} months of learning of the breach and the offender, and must be concluded within {1} months of initiation; if the breach has the features of a criminal offence, it may be initiated within 6 months of learning of it ({2}). A measure cannot be enforced if {3} days have passed since the decision became final and enforcement has not begun; a warning, fine and conditional termination are removed from the records if the employee does not commit a new breach within {4} years ({5}). A fine is deducted from salary under a final decision, so that total deductions without the employee's consent do not exceed one third of the salary ({6}).",
