"Rulebook 34/12 Art. 11: a change in the price of goods in stock is recorded on the basis of the stocktake report (price revaluation).",
"Rulebook 34/12 Art. 11: a change in the price of goods is entered in the trade records on the basis of the stocktake report. An increase is entered as a debit, a decrease as a red cancellation (col. 4). The new price applies from the day of the revaluation in the stock list and the cash register price list; the price history remains (Consumer Protection Act Art. 15).",
"Rulebook 34/12 Art. 3 para. 1: the records are kept separately for each wholesale point and shop. Wholesale: records EV, accounts 1320/1329, 5012, 6020. Retail: records EM, accounts 134000/134001/134002, 5013, 6021. The type can be changed only while the outlet has no documents.",
"Rulebook 34/12 Art. 3: trade records are kept separately for each point of sale. Sender: col. 4 red cancellation at its selling value; recipient: col. 4 charge per the internal costing sheet. PPZPDV Art. 80: internal receipts do not affect the tax liability.",
