"Turnover of goods is a transfer of the right of disposal (VAT Act Art. 4 para. 1) and arises on delivery: the delivery note reduces stock and the trade ledger on the delivery date (Rulebook 34/12 Art. 7 col. 5). A delivery note is not a fiscal receipt and does not enter KIF or PR-PDV. If an invoice has not been issued, VAT is calculated eight days after the delivery date (VAT Act Art. 18 para. 3); an invoice issued later receives that date of the tax liability.",
