"An equipment issue form is not a receipt. Goods issued on an equipment issue form remain company property until returned; sale is documented by a receipt. By signing, the recipient confirms receipt of the goods and the obligation to return them within the deadline.",
"No regulation mentions an equipment issue form. An interpretation closer to the text of ZPDV Art. 4 para. 1 (a supply is the transfer of the right to dispose): goods on an issue form are not sold and remain company property; they are booked out only by a receipt (Rulebook 34/12 Art. 7 col. 5), and a return has no entry in the trade ledger. Stock: outflow on the issue date, inflow on the return date. Another interpretation: if the recipient disposes of the goods, the supply has been made (VAT at the latest 8 days after handover, ZPDV Art. 18 para. 3). Goods on an issue form are counted on a separate stocktake list (Stocktake Rulebook, Art. 2).",
