"For a lesser breach a warning or a fine of up to {0} % of the monthly salary earned in the month of imposition is imposed, for a period of {1} to {2} months. For a more serious breach a fine of {3} to {4} % of the monthly salary for a period of {5} to {6} months is imposed, conditional termination of employment (employment ends if the employee commits a new serious breach within {7} months) or termination of employment ({8}). In imposing the measure, the seriousness and consequences of the breach, the degree of responsibility, previous work and conduct, previously imposed measures and other circumstances are taken into account ({9}). A third lesser breach within 12 months is treated as an aggravating circumstance.",
"For a minor breach, a warning or a fine of up to {0} % of the monthly salary is imposed for a period of {1} to {2} months; for a serious breach, a fine of {3} to {4} % of the monthly salary for a period of {5} to {6} months, conditional termination of the employment relationship or termination of the employment relationship ({7}). The measure is imposed under the procedure set out in {8}, in which the Employee has the right to make a statement in writing and orally. The Employee is liable for damage that he or she causes to the Employer intentionally or by gross negligence at work or in connection with work; the existence and amount of damage is determined by the Employer's commission ({9}). Salary may be withheld only after the procedure has been conducted, on the basis of a court decision or with the Employee's consent ({10}).",
